    def test_the_reading_log_does_not_scale_with_the_history(self, client_a, tenant_a, asset_a,
                                                             meter_reading_a):
        from apps.scm.models import MeterReading
        small = _returns_query_count(client_a, reverse("scm:meterreading_list"))
